<?php
declare(strict_types=1);

/**
 * install_admin_db_backup_manager_v1_7_v001.php
 *
 * VERSION: v001
 * LAST MODIFIED: 8/29/2026 7:00:54 am
 *
 * TARGET:
 *   /admin_db_backup.php v1.6 -> v1.7
 *
 * CHANGES:
 * - To Be Deleted becomes a simple manual holding area.
 * - Removes the 30-day eligibility rule.
 * - Moving files no longer changes file modified timestamps.
 * - Permanent delete requires explicit confirmation only.
 * - Preserves all v1.6 restore / archive / rename / select-all behavior.
 *
 * LOCATION:
 * Put this installer in public_html/.
 */

date_default_timezone_set('America/New_York');

const BASE_SHA256 = '527bf157504e2048439e421fc63147fa4a383fc6eaf3f3df0bf858a5b6c4ea95';
const NEW_SHA256  = '71c5db7ff67a741d0edab26b80bf967c0cb834b515035b530c55e4d06520ea9d';

$target = __DIR__ . '/admin_db_backup.php';
$replacement = base64_decode('', true);

function ih(string $v): string { return htmlspecialchars($v, ENT_QUOTES, 'UTF-8'); }
function row(string $label, bool $ok, string $detail=''): void {
    echo '<tr><td>'.ih($label).'</td><td class="'.($ok?'ok':'bad').'">'.($ok?'PASS':'FAIL').'</td><td>'.ih($detail).'</td></tr>';
}
function atomic_write(string $path, string $data): bool {
    $tmp=$path.'.tmp_'.bin2hex(random_bytes(4));
    if(file_put_contents($tmp,$data,LOCK_EX)===false)return false;
    if(!@rename($tmp,$path)){@unlink($tmp);return false;}
    return true;
}

$exists=is_file($target);
$currentHash=$exists?(string)hash_file('sha256',$target):'';

$baselineOk=$exists
    && $currentHash===BASE_SHA256
    && strpos((string)file_get_contents($target),'wireRenameAutoFill')!==false
    && strpos((string)file_get_contents($target),'setBackupChecks')!==false
    && strpos((string)file_get_contents($target),'Permanently Delete Checked Eligible Files')!==false;

$replacementOk=is_string($replacement)
    && hash('sha256',$replacement)===NEW_SHA256
    && strpos($replacement,'v1.7  (8/29/2026 7:00:54 am)')!==false
    && strpos($replacement,'Manual safety holding area.')!==false
    && strpos($replacement,'Permanently Delete Checked</button>')!==false
    && strpos($replacement,'deleteRetentionDays')===false
    && strpos($replacement,'quarantineEligibleInfo')===false
    && strpos($replacement,'@touch($dst)')===false;

$preflightOk=$baselineOk&&$replacementOk;
$apply=isset($_POST['apply'])&&$_POST['apply']==='1';
$messages=[];$success=false;

if($apply&&$preflightOk){
    $backupDir=__DIR__.'/_migration_backups/admin_db_backup_v17_'.date('Ymd_His');
    $ok=is_dir($backupDir)||mkdir($backupDir,0755,true);

    if(!$ok)$messages[]='FAIL: Could not create installer backup directory.';

    if($ok&&!copy($target,$backupDir.'/admin_db_backup.php')){
        $ok=false;
        $messages[]='FAIL: Could not back up admin_db_backup.php v1.6.';
    } elseif($ok) {
        $messages[]='PASS: Backed up admin_db_backup.php v1.6.';
    }

    if($ok&&!atomic_write($target,$replacement)){
        $ok=false;
        $messages[]='FAIL: Could not install admin_db_backup.php v1.7.';
    } elseif($ok) {
        $messages[]='PASS: Installed admin_db_backup.php v1.7.';
    }

    if($ok){
        $installed=(string)file_get_contents($target);
        $checks=[
            'v1.7 version history'=>strpos($installed,'v1.7  (8/29/2026 7:00:54 am)')!==false,
            '30-day rule removed'=>strpos($installed,'deleteRetentionDays')===false,
            'quarantine metadata helper removed'=>strpos($installed,'quarantineEligibleInfo')===false,
            'file timestamp touch removed'=>strpos($installed,'@touch($dst)')===false,
            'simple delete confirmation'=>strpos($installed,"PERMANENTLY DELETE the checked file(s)?")!==false,
            'To Be Deleted shows original Modified date'=>strpos($installed,'<th style="width:160px;">Modified</th>')!==false,
            'v1.6 rename auto-fill retained'=>strpos($installed,'wireRenameAutoFill')!==false,
            'v1.6 Select All / Clear retained'=>strpos($installed,'setBackupChecks')!==false,
            'Archive retained'=>strpos($installed,'Archive Checked')!==false,
            'replacement hash exact'=>hash_file('sha256',$target)===NEW_SHA256,
        ];
        foreach($checks as $label=>$pass){
            $messages[]=($pass?'PASS: ':'FAIL: ').$label;
            if(!$pass)$ok=false;
        }
    }

    if(!$ok&&is_file($backupDir.'/admin_db_backup.php')){
        if(copy($backupDir.'/admin_db_backup.php',$target))$messages[]='ROLLBACK: Restored admin_db_backup.php v1.6.';
        else $messages[]='ROLLBACK ERROR: Could not restore admin_db_backup.php v1.6.';
    } else {
        $success=true;
    }
}
?><!doctype html>
<html><head><meta charset="utf-8"><title>Install DB Backup Manager v1.7</title>
<style>*{box-sizing:border-box}html{background:#111}body{margin:0;color:#eee;font-family:Tahoma,Verdana,sans-serif}.wrap{width:94%;max-width:1100px;margin:20px auto}.card{background:#202020;border:1px solid #555;border-radius:14px;padding:20px;margin-bottom:16px}h1,h2{color:#efc982}table{width:100%;border-collapse:collapse}td{padding:9px;border-bottom:1px solid #444}.ok{color:#61e493}.bad{color:#ff7777}button{padding:11px 20px;background:#1466c9;color:white;border:0;border-radius:9px;font-weight:800}a,code{color:#76cfff}</style>
</head><body><div class="wrap">
<div class="card"><h1>Admin DB Backup Manager v1.7</h1><p>Simplified delete holding area; original file dates preserved.</p></div>
<div class="card"><h2>Preflight</h2><table>
<?php row('Exact production admin_db_backup.php v1.6 baseline',$baselineOk,$currentHash); ?>
<?php row('Complete v1.7 replacement embedded',$replacementOk,NEW_SHA256); ?>
</table></div>

<?php if($preflightOk): ?>
<div class="card"><h2>What changes</h2><ul>
<li><strong>No more 30-day rule.</strong> To Be Deleted is simply a manual holding area.</li>
<li>Moving files no longer changes their modified timestamps.</li>
<li>No JSON, metadata file, or other tracking is introduced.</li>
<li>Permanent Delete remains manual and requires an explicit confirmation.</li>
<li>Rename auto-fill, Select All / Clear, Archive, Restore, and all DB backup/restore behavior remain intact.</li>
</ul>
<?php if(!$apply): ?><form method="post"><input type="hidden" name="apply" value="1"><button>Install DB Backup Manager v1.7</button></form><?php endif; ?>
</div>
<?php endif; ?>

<?php if($apply): ?>
<div class="card"><h2>Apply Result</h2>
<p class="<?php echo $success?'ok':'bad'; ?>"><strong><?php echo $success?'SUCCESS':'FAILED / ROLLED BACK'; ?></strong></p>
<ul><?php foreach($messages as $m): ?><li><?php echo ih($m); ?></li><?php endforeach; ?></ul>
<?php if($success): ?><p><a href="/admin_db_backup.php" target="_blank">Open Admin DB Backup Manager v1.7</a></p><?php endif; ?>
</div>
<?php endif; ?>

</div></body></html>